"""Bind generated corridor source review and its narrow regression evidence."""
from pathlib import Path
import ast,hashlib,json
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).resolve().parent;C=ROOT/'build/healthy-corridor-bridge-v1'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
expected={'healthy_corridor.py':'2deee9a16364f49f2b33c4e2f64cd92eaca15abfd392888e3777741979b81277','test_corridor.py':'ab2af99c99a59b1a7a333c148868261bd708acf54f5173aa046f324ad19c941d','candidate.patch':'55dd5822be5c2c0ba82f5801aea32aab4b2a18718e87b1ac187c91692e10f786'}
for name,value in expected.items():assert sha(C/name)==value
receipt=json.loads((OUT/'test-review.json').read_text())
assert receipt['status']=='PASS' and receipt['pytest_exit_code']==0 and not receipt['blocked_payload_or_network_attempts']
assert not receipt['policy_library_imported'] and not receipt['image_library_imported']
assert receipt['source_hashes_before']==receipt['source_hashes_after']
for path,value in receipt['source_hashes_after'].items():assert sha(ROOT/path)==value
parts={};target=None
for line in (C/'candidate.patch').read_text().splitlines(keepends=True):
 if line.startswith('+++ b/'):
  target=line.removeprefix('+++ b/').strip();parts[target]=[]
 elif line.startswith('--- '):target=None
 elif target and line.startswith('+'):parts[target].append(line[1:])
assert ''.join(parts['src/resectionlab/healthy_corridor.py'])==(C/'healthy_corridor.py').read_text()
testpath=next(p for p in parts if p.startswith('tests/'));promoted=''.join(parts[testpath])
def funcs(code):return {n.name:ast.dump(n) for n in ast.parse(code).body if isinstance(n,ast.FunctionDef)}
assert funcs(promoted)==funcs((C/'test_corridor.py').read_text())
report={'schema':'healthy-corridor-independent-review-v1','decision':'GO_generated_only_source_integration','candidate_sha256':expected,'tests':{'author_controls':33,'independent_controls':14,'passed':47,'pytest_seconds':2.41,'source_and_reused_kernel_bytes_unchanged':True,'promotion_source_exact_and_test_functions_unchanged':True,'actual_payload_or_network_attempts':0,'policy_or_image_library_imported':False},'source_sha256':receipt['source_hashes_after'],'evidence_sha256':{name:sha(OUT/name) for name in ['initial-findings.json','reproduce_initial_findings.py','test_independent_corridor.py','run_review_tests.py','combined-tests.txt','test-review.json']},'resolved_findings':[{'issue':'Two requested interior waypoints collapsed to the same cell when only two interior cells existed.','original_reproduction':[[7.,7.,11.],[7.,7.,11.]],'repair':'Deterministic n*(index+1)//(count+1) quantiles select distinct eligible cells.'},{'issue':'A resealed SEARCH record could select suboptimal STOP and supply arbitrary nonnegative comparison counts; noncomplete rows skipped accounting checks.','repair':'Derived exhaustive optimum, semantic payload seal, exact complete and bounded noncomplete method-specific callback/comparison/zero-forward/update accounting. Manifest budget identity is type-sensitive.'},{'issue':'A public actor mapping altered after preparation could bypass support fit-role/kind/exposure and dependency-availability assertions.','original_reproduction':'support.project_fit_roles=[SELECT] accepted by original constructor','repair':'Recheck existing actor-only metadata invariants; private metadata stays out of task construction.'},{'issue':'Source identity omitted the contact wrapper underlying segment-box oracle.','repair':'Include independent_geometry_batch.py hash in task/source binding.'}],'reviewed_boundaries':['Generated-only exact public actor fields and immutable T1/support/coverage inputs on whole supplied <=16^3 ROI; no silent crop or GENERATED_T1/tumor aliases.','At most2 tools x2 deterministic interior waypoints; one-step objective is reach_credit minus round-trip physical-mm effort. No removal reward or cavity evolution.','Ordinary brain support is an exposure mask; unknown public coverage is forbidden. Full tool starts outside support and stays within the supplied ROI. This is hypothetical geometric corridor feasibility only.','SEARCH and HYBRID choose the exact complete public-table optimum including STOP; scripted IL/RL callbacks return one legal action or abstain. STOP, failed and abstained slots stay distinct.','All four terminal slots and complete versioned insertion/reverse-withdrawal histories are durable before private input; every complete history receives independent motion checks before the single private callback.','Private contract is copied, source/frame/directed rigid registration/domain identities checked; common <=32^3 generated MRA/mask/domain arrays are snapshotted and hash checked.','Reused tiled capsule scorer evaluates complete shaft/tip insertion/withdrawal unions; caller array mutation cannot retarget later methods. Failed private/batch checks clear all endpoint scores without dropping method slots.','No post-private nominal generation, policy decision or independent planning preflight; no policy checkpoint/model/training/patient or external native solver operation.'],'limits':['This is an executable generated interface/control bridge, not an IL/RL efficacy experiment or real-person admission. Selectors are explicitly scripted; old learned checkpoints are not validated for this objective.','Actor role/source membership derives from metadata preparation; actor mapping/content hashes are not provenance authentication or hostile-Python isolation. Real evidence domains are refused.','Ordinary support exposure does not certify surgical penetration, tissue mechanics, cavity feasibility, biological vessel absence or clinical injury.','Continuous axial sweeps cover full insertion and reverse withdrawal; contact volumes are cell-based exposure surrogates, not tissue removal or dose/damage.','The supplied ROI caps remain 16^3 public and 32^3 private, with at most 2 tools, 2 waypoints, 4 candidate rows and horizon 1. No full real-volume claim.','Callbacks are synchronous. Per-contact cooperative budget is not an overall hard time/memory supervisor for arbitrary selector/loader code. Zero model-forward/update fields describe the scripted protocol rather than instrumenting hostile callbacks.','Successful contact work counters are supplied by the reused kernel; failed batch reports retain null endpoints and the fixed denominator, not a complete benchmark resource ledger.','No new anatomy/QC gate is added to continuous opaque intake. Real patient execution would require separately reviewed admission, objective/estimator/policy compatibility, frame/domain evidence and supervision.'],'tracked_edits_by_reviewer':False,'root_only_integration':True}
(OUT/'review.json').write_text(json.dumps(report,indent=2,sort_keys=True)+'\n')
text='''# Independent generated healthy-corridor bridge review

GO for root-only integration of the exact generated-only source. All 47 controls pass in 2.41 seconds: 33 author controls and 14 independent controls. Source and all eight reused implementation files remained unchanged during testing. The promotion patch preserves exact source and test function bodies. No patient/model/archive payload, network, training, model forward or external native solver call occurred.

Three reproduced issues are repaired: duplicate waypoints in the two-interior-cell case, acceptance of a resealed suboptimal SEARCH STOP/accounting, and acceptance of an altered protected fit-role assertion after metadata preparation. The final source enforces distinct deterministic quantiles, semantic seals and exhaustive SEARCH/HYBRID choices, method-specific accounting for every slot, type-sensitive budgets, and the existing actor-only metadata invariants. The source identity now includes the segment-box oracle beneath the contact wrapper. Legitimate STOP remains valid when every legal route has a negative public objective.

The public task uses immutable T1/support/coverage on the whole supplied bounded ROI. Its objective is waypoint reach minus round-trip millimetre effort, not removal. Full tool geometry starts outside support and remains inside qualified public coverage. Support is measured as ordinary-tissue exposure; the legal flag establishes a hypothetical geometric query, not a surgically feasible path through tissue.

All four terminal slots and complete versioned insertion/reverse-withdrawal histories are durable before private access. Independent motion checks finish for all complete histories before the single private callback. The copied private contract and snapshotted MRA/mask/domain arrays define one reference world. Private array mutation cannot alter later methods' results. The reused tiled scorer checks full shaft/tip capsule unions. STOP, abstention and failures retain distinct records; private integrity failure clears scores while preserving the denominator.

This validates the generated bridge and scripted callback protocol only. It provides no trained IL/RL comparison, old-checkpoint compatibility, real-person admission, surgical penetration/removal/mechanics claim, vessel-completeness claim or clinical-injury estimate. Source-role assertions remain grounded in metadata preparation rather than authenticated by the actor mapping. The 16^3/32^3 ROI caps and one-step objective remain explicit; synchronous callbacks still require external supervision for real use. No QC gate is added to ongoing byte intake.

Exact SHA-256 bindings:

'''
for name,value in expected.items():text+=f'- `{name}`: `{value}`\n'
text+=f'\nMachine review: `review.json` SHA-256 `{sha(OUT/"review.json")}`. Evidence and reused-source hashes are included there.\n'
(OUT/'REPORT.md').write_text(text)
print(json.dumps({'decision':report['decision'],'report_sha256':sha(OUT/'REPORT.md'),'review_sha256':sha(OUT/'review.json'),'test_review_sha256':sha(OUT/'test-review.json')},indent=2))
